"use client"

import * as React from "react"

import { type Classification } from "@/lib/retab"
import { cn } from "@/lib/utils"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"

export interface ClassificationViewerProps {
  classification: Classification
  className?: string
}

export function ClassificationViewer({
  classification,
  className,
}: ClassificationViewerProps) {
  const decision = classification.output
  const phase = useViewerPhase({
    status: classification.status,
    error: classification.error,
    hasOutput: Boolean(decision),
  })

  const likelihood = classification.consensus?.likelihoods ?? null
  const categories = classification.categories ?? []

  return (
    <RetabViewerShell
      title={classification.file?.filename ?? "Classification"}
      status={classification.status}
      error={classification.error}
      phase={phase}
      emptyMessage="No category was assigned."
      className={className}
    >
      <div className="flex flex-col gap-5 p-4">
        <div className="flex flex-col gap-2">
          <span className="text-xs font-medium text-muted-foreground">
            Predicted category
          </span>
          <div className="flex items-center gap-3">
            <span
              data-slot="classification-category"
              className="inline-flex items-center rounded-md bg-primary/10 px-2.5 py-1 text-sm font-semibold text-primary"
            >
              {decision?.category}
            </span>
            {likelihood != null ? (
              <ConfidenceMeter value={likelihood} />
            ) : null}
          </div>
        </div>

        {decision?.reasoning ? (
          <div className="flex flex-col gap-1.5">
            <span className="text-xs font-medium text-muted-foreground">
              Reasoning
            </span>
            <p className="text-sm leading-relaxed text-foreground/90">
              {decision.reasoning}
            </p>
          </div>
        ) : null}

        {categories.length > 0 ? (
          <div className="flex flex-col gap-2">
            <span className="text-xs font-medium text-muted-foreground">
              Candidate categories
            </span>
            <ul className="flex flex-col gap-1">
              {categories.map((category) => {
                const isWinner = category.name === decision?.category
                return (
                  <li
                    key={category.name}
                    data-active={isWinner}
                    className={cn(
                      "flex items-start gap-2 rounded-md border border-transparent px-2 py-1.5 text-sm",
                      isWinner && "border-border bg-muted/50"
                    )}
                  >
                    <span
                      aria-hidden
                      className={cn(
                        "mt-1.5 size-1.5 shrink-0 rounded-full",
                        isWinner ? "bg-primary" : "bg-muted-foreground/40"
                      )}
                    />
                    <div className="min-w-0">
                      <div className="font-medium">{category.name}</div>
                      {category.description ? (
                        <div className="text-xs text-muted-foreground">
                          {category.description}
                        </div>
                      ) : null}
                    </div>
                  </li>
                )
              })}
            </ul>
          </div>
        ) : null}
      </div>
    </RetabViewerShell>
  )
}

function ConfidenceMeter({ value }: { value: number }) {
  const pct = Math.round(Math.max(0, Math.min(1, value)) * 100)
  return (
    <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
      <span className="h-1.5 w-16 overflow-hidden rounded-full bg-muted">
        <span
          className="block h-full rounded-full bg-primary"
          style={{ width: `${pct}%` }}
        />
      </span>
      {pct}%
    </span>
  )
}

export { type Classification }
